import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.B0p3fmqd.js";const s="/script-documentation/images/towscenarios.jpg",g=JSON.parse('{"title":"Tow Scenarios","description":"","frontmatter":{},"headers":[],"relativePath":"towscenarios/index.md","filePath":"towscenarios/index.md","lastUpdated":1791039789000}'),i={name:"towscenarios/index.md"};function n(l,e,c,d,h,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="tow-scenarios" tabindex="-1">Tow Scenarios <a class="header-anchor" href="#tow-scenarios" aria-label="Permalink to &quot;Tow Scenarios&quot;">​</a></h1><p><img src="'+s+'" alt="Tow Scenarios"></p><p>A full tow company. Players take roadside call-outs, recover wrecks, chop vehicles and run their own businesses.</p><div class="info custom-block"><p class="custom-block-title">Version 5.1.0</p><p>Requires <code>community_bridge</code>, <code>ox_lib</code> and <code>oxmysql</code>. Everything else is picked up automatically.</p></div><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li><strong>Dynamic call-outs.</strong> Jobs appear on a timer and are dispatched to tow drivers with a map blip and a dialogue from the stranded driver.</li><li><strong>Scenarios.</strong> Breakdowns, minor and severe crashes, two-vehicle collisions, head-on collisions, rollovers, car fires, battery runs, tyre changes and a train derailment.</li><li><strong>Fire scenes.</strong> Put fires out with an extinguisher before the car explodes. Fires can flare back up, and the fire bonus is shared between everyone who sprayed.</li><li><strong>Rescue work.</strong> Revive casualties, call the ambulance and bag the ones who did not make it.</li><li><strong>Bystanders.</strong> Pedestrians near a scene flee or stop to film.</li><li><strong>Chop shop.</strong> Strip vehicles for parts and export them for a profit.</li><li><strong>Repair bay and spares shop.</strong> Buy a battery, a tyre, a fire extinguisher or a crowbar.</li><li><strong>Player owned companies.</strong> Buy and sell tow companies, with XP, levels and rewards for drivers.</li><li><strong>Admin tools.</strong> Place everything in game with <code>/towcreator</code>.</li></ul><h2 id="get-started" tabindex="-1">Get started <a class="header-anchor" href="#get-started" aria-label="Permalink to &quot;Get started&quot;">​</a></h2><ol><li><a href="/script-documentation/towscenarios/installation">Install the script</a></li><li><a href="/script-documentation/towscenarios/configuration">Configure it</a></li><li>See what changed in the <a href="/script-documentation/towscenarios/changelog">changelog</a></li></ol>',8)])])}const m=a(i,[["render",n]]);export{g as __pageData,m as default};
